(function(){function init(){document.querySelectorAll('header[data-word-shared] .nove-service-dropdown').forEach(function(w){if(w.dataset.bound)return;w.dataset.bound='true';var b=w.querySelector('button'),m=w.querySelector('.nove-service-menu');function set(open){m.hidden=!open;b.setAttribute('aria-expanded',String(open));}b.addEventListener('click',function(){set(m.hidden)});document.addEventListener('click',function(e){if(!w.contains(e.target))set(false)});w.addEventListener('keydown',function(e){if(e.key==='Escape'){set(false);b.focus();e.stopPropagation()}if(e.key==='ArrowDown'&&e.target===b){e.preventDefault();set(true);m.querySelector('a').focus()}});w.addEventListener('focusout',function(){setTimeout(function(){if(!w.contains(document.activeElement))set(false)},0)});});}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
